<?php $members = sd_homepage_members(); if ( empty( $members ) ) { return; } ?><section class="sd-home-section sd-home-people"><div class="sd-container"><?php sd_homepage_heading( __( 'Meet', 'social-discovery' ), sd_homepage_get( 'sd_home_people_heading' ), __( 'Discover members who have chosen to be part of the public community.', 'social-discovery' ) ); ?><div class="<?php echo esc_attr( sd_homepage_grid_class( sd_homepage_get( 'sd_home_people_columns' ) ) ); ?>"><?php foreach ( $members as $member ) : $member_id = isset( $member->ID ) ? $member->ID : 0; $name = function_exists( 'bp_core_get_user_displayname' ) ? bp_core_get_user_displayname( $member_id ) : get_the_author_meta( 'display_name', $member_id ); ?><article class="sd-home-card sd-home-person-card"><div class="sd-home-person-avatar"><img src="<?php echo esc_url( sd_avatar( $member_id, 96 ) ); ?>" alt="<?php echo esc_attr( $name ); ?>" loading="lazy"></div><h3><?php echo esc_html( $name ); ?></h3><?php if ( sd_homepage_get( 'sd_home_people_bio' ) && ! empty( $member->display_name ) ) : ?><p><?php echo esc_html( wp_trim_words( get_the_author_meta( 'description', $member_id ), 18 ) ); ?></p><?php endif; ?><a class="sd-button sd-button-outline" href="<?php echo esc_url( sd_get_member_url( $member_id ) ); ?>"><?php esc_html_e( 'View profile', 'social-discovery' ); ?></a></article><?php endforeach; ?></div></div></section>
